"""Resolve and launch the untouched Official-launcher profile generated by Ornithe."""
import concurrent.futures
import datetime
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import shutil
import subprocess
import sys
import time
import urllib.error
import urllib.request
import zipfile

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
WORK = ROOT / 'build/v1-release-checks'
INSTALL = WORK / 'installer-instance'
JDK = Path(r'C:\Program Files\Eclipse Adoptium\jdk-25.0.4.101-hotspot')
MINECRAFT = Path(os.environ['APPDATA']) / '.minecraft'
GRADLE = Path.home() / '.gradle/caches'
PROFILE = 'fabric-loader-0.20.0-1.8.9-ornithe-gen2'


def sha(path, algorithm='sha256'):
    return hashlib.new(algorithm, Path(path).read_bytes()).hexdigest()


def allowed(rules):
    result = not rules
    for rule in rules:
        spec = rule.get('os', {})
        matches = (spec.get('name', 'windows') == 'windows'
                   and ('arch' not in spec or re.search(spec['arch'], 'amd64'))
                   and ('version' not in spec or re.search(spec['version'], platform.version()))
                   and not any(rule.get('features', {}).values()))
        if matches: result = rule['action'] == 'allow'
    return result


def fetch(path, url, hashes=None, candidates=()):
    path = Path(path)
    hashes = hashes or {}
    def valid(p):
        return p.is_file() and all(sha(p, alg) == value.zfill(hashlib.new(alg).digest_size * 2)
                                  for alg, value in hashes.items() if alg in ('sha1', 'sha256'))
    path.parent.mkdir(parents=True, exist_ok=True)
    if valid(path): return
    for candidate in candidates:
        if valid(candidate):
            shutil.copy2(candidate, path)
            return
    path.write_bytes(urllib.request.urlopen(url, timeout=45).read())
    if not valid(path): raise RuntimeError('Hash mismatch: ' + url)


def coordinate(name):
    group, artifact, version, *classifier = name.split(':')
    filename = artifact + '-' + version + ('-' + classifier[0] if classifier else '') + '.jar'
    return '/'.join([group.replace('.', '/'), artifact, version, filename])


def prepare():
    chain = []
    name = PROFILE
    while name:
        path = INSTALL / 'versions' / name / (name + '.json')
        data = json.loads(path.read_text())
        chain.insert(0, (path, data))
        name = data.get('inheritsFrom')
    libraries, jvm, game = {}, [], []
    for _, data in chain:
        for lib in data.get('libraries', []):
            key = ':'.join(lib['name'].split(':')[:2])
            libraries[key] = lib
        jvm += data.get('arguments', {}).get('jvm', [])
        game += data.get('arguments', {}).get('game', [])
    native = WORK / 'natives'
    native.mkdir(exist_ok=True)
    cp, records = [], []
    for lib in libraries.values():
        if not allowed(lib.get('rules', [])): continue
        relative = coordinate(lib['name'])
        downloads = lib.get('downloads')
        artifact = (downloads or {}).get('artifact')
        if downloads is None:
            artifact = {'path': relative, 'url': lib.get('url', 'https://libraries.minecraft.net/') + relative}
        if artifact:
            relative = artifact.get('path', relative)
            target = INSTALL / 'libraries' / relative
            group, package, version, *_ = lib['name'].split(':')
            cache = GRADLE / 'modules-2/files-2.1' / group / package / version
            candidates = [MINECRAFT / 'libraries' / relative, *cache.glob('*/' + Path(relative).name)]
            hashes = {k: artifact.get(k, lib.get(k)) for k in ('sha1', 'sha256') if artifact.get(k, lib.get(k))}
            if not hashes:
                for alg in ('sha256', 'sha1'):
                    try:
                        hashes[alg] = urllib.request.urlopen(artifact['url'] + '.' + alg, timeout=10).read().decode().split()[0]
                        break
                    except urllib.error.HTTPError: pass
            fetch(target, artifact['url'], hashes, candidates)
            cp.append(str(target))
            records.append({'name': lib['name'], 'url': artifact['url'], 'sha256': sha(target), 'declared_hashes': hashes})
        classifier = lib.get('natives', {}).get('windows')
        if classifier:
            classifier = classifier.replace('${arch}', '64')
            artifact = lib['downloads']['classifiers'][classifier]
            target = INSTALL / 'libraries' / artifact['path']
            fetch(target, artifact['url'], {'sha1': artifact['sha1']}, [MINECRAFT / 'libraries' / artifact['path']])
            records.append({'name': lib['name'] + ':' + classifier, 'url': artifact['url'], 'sha256': sha(target)})
            with zipfile.ZipFile(target) as archive:
                for member in archive.infolist():
                    if member.is_dir() or member.filename.startswith('META-INF/'): continue
                    dest = (native / member.filename).resolve()
                    if not dest.is_relative_to(native.resolve()): raise RuntimeError('Unsafe native archive path')
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    dest.write_bytes(archive.read(member))
    base = chain[0][1]
    client = base['downloads']['client']
    jar = INSTALL / 'versions' / base['id'] / (base['id'] + '.jar')
    fetch(jar, client['url'], {'sha1': client['sha1']}, [MINECRAFT / 'versions/1.8.9/1.8.9.jar', GRADLE / 'fabric-loom/1.8.9/minecraft-client.jar'])
    cp.append(str(jar))
    assets = WORK / 'assets'
    index = base['assetIndex']
    index_path = assets / 'indexes' / (index['id'] + '.json')
    fetch(index_path, index['url'], {'sha1': index['sha1']})
    objects = json.loads(index_path.read_text())['objects']
    unique_objects = {item['hash']: item for item in objects.values()}
    def asset(item):
        digest = item['hash']; rel = digest[:2] + '/' + digest
        fetch(assets / 'objects' / rel, 'https://resources.download.minecraft.net/' + rel,
              {'sha1': digest}, [GRADLE / 'fabric-loom/assets/objects' / rel, MINECRAFT / 'assets/objects' / rel])
    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
        list(pool.map(asset, unique_objects.values()))
    logging = chain[-1][1]['logging']['client']
    log_config = WORK / logging['file']['id']
    fetch(log_config, logging['file']['url'], {'sha1': logging['file']['sha1']})
    prepared = {'chain': [str(p) for p, _ in chain], 'profile_hashes': {str(p.relative_to(INSTALL)): sha(p) for p, _ in chain},
                'libraries': records, 'classpath': cp, 'jvm': jvm, 'game': game,
                'main_class': chain[-1][1]['mainClass'], 'native': str(native), 'assets': str(assets),
                'asset_index': index['id'], 'logging_argument': logging['argument'].replace('${path}', str(log_config))}
    (WORK / 'prepared-profile.json').write_text(json.dumps(prepared, indent=2) + '\n')
    print(json.dumps({'libraries': len(records), 'asset_objects': len(objects), 'profile_jvm': jvm[-2:]}, indent=2))


def expand(values, substitutions):
    result = []
    for entry in values:
        if isinstance(entry, dict):
            if not allowed(entry.get('rules', [])): continue
            entry = entry['value']
        for text in entry if isinstance(entry, list) else [entry]:
            for key, value in substitutions.items(): text = text.replace('${' + key + '}', value)
            if '${' in text: raise RuntimeError('Unexpanded profile argument: ' + text)
            result.append(text)
    return result


def launch(label, soak=False):
    target = HERE / 'launches' / (label + '.json')
    target.parent.mkdir(exist_ok=True)
    if target.exists(): raise RuntimeError('Attempt exists: ' + label)
    prepared = json.loads((WORK / 'prepared-profile.json').read_text())
    for name, expected in prepared['profile_hashes'].items():
        if sha(INSTALL / name) != expected: raise RuntimeError('Installer metadata changed')
    game = WORK / label
    game.mkdir(exist_ok=False)
    (game / 'mods').mkdir(); (game / 'saves').mkdir()
    artifact = ROOT / 'build/libs/alacer-1.0.0+mc1.8.9.jar'
    shutil.copy2(artifact, game / 'mods' / artifact.name)
    original_mods = (ROOT / '.gradle/loom-cache/remapClasspath.txt').read_text().split(';')
    for file in original_mods:
        if 'net.ornithemc.osl-gen2' in file: shutil.copy2(file, game / 'mods' / Path(file).name)
    options = (ROOT / 'run/options.txt').read_text()
    options = re.sub(r'(?m)^soundCategory_master:[^\r\n]*', 'soundCategory_master:0.0', options)
    (game / 'options.txt').write_text(options)
    shutil.copytree(ROOT / 'run/saves/alacer-benchmark', game / 'saves/alacer-benchmark')
    substitutions = dict(natives_directory=prepared['native'], launcher_name='AlacerProfileTest', launcher_version='1',
        classpath=';'.join(prepared['classpath']), auth_player_name='ProfileTest', version_name=PROFILE,
        game_directory=str(game), assets_root=prepared['assets'], assets_index_name=prepared['asset_index'],
        auth_uuid='00000000000000000000000000000001', auth_access_token='0', user_properties='{}', user_type='legacy')
    props = ['-Dalacer.benchmark=true', '-Dalacer.benchmark.label=' + label, '-Dalacer.benchmark.vbo=true',
             '-Dalacer.benchmark.entities=200', '-Dalacer.benchmark.screenshots=true', '-Dalacer.profiler.hud=false',
             '-Dalacer.benchmark.timeout=' + ('660' if soak else '180')]
    props += ['-Dalacer.benchmark.phaseSeconds=static:60,pan:120,fly:300'] if soak else ['-Dalacer.benchmark.timeScale=0.35']
    args = ['-Xmx4G' if soak else '-Xmx2G', '--enable-native-access=ALL-UNNAMED', '--add-modules=jdk.incubator.vector',
            '-Xlog:class+load=info:file=class-load.log', prepared['logging_argument'], *props,
            *expand(prepared['jvm'], substitutions), prepared['main_class'],
            *expand(prepared['game'], substitutions), '--width', '1280', '--height', '720']
    argfile = game / 'java.args'
    argfile.write_text('\n'.join('"' + a.replace('\\', '\\\\').replace('"', '\\"') + '"' for a in args), encoding='utf-8')
    record = dict(label=label, args=args, java=str(JDK / 'bin/java.exe'), game_dir=str(game), status='running',
        source=subprocess.check_output(['git', 'rev-parse', 'HEAD'], text=True).strip(), jar_sha256=sha(artifact),
        profile_hashes=prepared['profile_hashes'], master_volume='0.0',
        started_utc=datetime.datetime.now(datetime.timezone.utc).isoformat())
    target.write_text(json.dumps(record, indent=2) + '\n')
    start = time.monotonic()
    with (game / 'launcher.log').open('w', encoding='utf-8') as output:
        process = subprocess.Popen([str(JDK / 'bin/java.exe'), '@' + str(argfile)], cwd=game, stdout=output, stderr=subprocess.STDOUT)
        try: record['exit_code'] = process.wait(timeout=720 if soak else 210)
        except subprocess.TimeoutExpired:
            process.kill(); record['exit_code'] = process.wait(); record['timeout'] = True
    record.update(duration_s=time.monotonic() - start, ended_utc=datetime.datetime.now(datetime.timezone.utc).isoformat())
    record['status'] = 'completed' if record['exit_code'] == 0 else 'failed'
    text = (game / 'launcher.log').read_text(errors='replace')
    errors = re.findall(r'^.*(?:OpenGL Error|GL ERROR|InvalidMixin|Unreported exception|EXCEPTION_ACCESS_VIOLATION|Benchmark timed out).*$', text, re.M)
    record['functional_errors'] = errors
    (HERE / 'logs').mkdir(exist_ok=True)
    (HERE / 'logs' / (label + '.log')).write_text('\n'.join(l.rstrip() for l in text.splitlines()) + '\n')
    classes = game / 'class-load.log'
    if classes.exists(): record['class_origins'] = [l for l in classes.read_text(errors='replace').splitlines() if 'net.adiont.alacer.Alacer source:' in l]
    summaries = list((game / 'alacer/benchmarks').glob('*/summary.json'))
    if len(summaries) == 1:
        folder = summaries[0].parent; summary = json.loads(summaries[0].read_text())
        record['phases'] = {n: {k: p[k] for k in ('frames', 'dropped_frames', 'recorded_wall_seconds')} for n, p in summary['phases'].items()}
        record['run'] = str(folder.relative_to(ROOT))
        dest = HERE / 'runs' / folder.name; dest.mkdir(parents=True, exist_ok=True)
        record['raw_files_sha256'] = {p.name: sha(p) for p in folder.iterdir() if p.is_file()}
        shutil.copy2(summaries[0], dest / 'summary.json')
        for p in (game / 'screenshots').glob('alacer-' + label + '-*.png'): shutil.copy2(p, dest / p.name)
    else: record['summary_missing'] = True
    target.write_text(json.dumps(record, indent=2) + '\n')
    print(json.dumps({k: record.get(k) for k in ('label', 'status', 'exit_code', 'duration_s', 'phases', 'functional_errors', 'summary_missing')}, indent=2), flush=True)
    if record['status'] != 'completed' or errors or record.get('summary_missing') or any(p['dropped_frames'] for p in record.get('phases', {}).values()):
        raise SystemExit('STOP: failed installer-profile gate')


if __name__ == '__main__':
    if sys.argv[1] == 'prepare': prepare()
    else: launch(sys.argv[1], '--soak' in sys.argv)
